33	// New creates a new Orchestrator.
34	func New(bus *eventbus.EventBus, cfg *config.WardConfig, target string, version string) *Orchestrator {
35		return &Orchestrator{bus: bus, cfg: cfg, target: target, version: version}
36	}
37	
38	// SetBaseline configures an existing baseline for filtering.
39	func (o *Orchestrator) SetBaseline(b *baseline.Baseline) {
40		o.baseline = b
41	}
42	
43	// SetBaselinePath configures a path to save a new baseline after scanning.
44	func (o *Orchestrator) SetBaselinePath(path string) {
45		o.baselinePath = path
46	}
47	
48	// Run executes the full scan pipeline.
49	func (o *Orchestrator) Run(ctx context.Context) error {
50		startTime := time.Now()
51	
52		scanners := []models.Scanner{
53			envscanner.New(),
54			configscanner.New(),
55			depscanner.New(),
56		}
57	
58		// Load custom YAML rules and add rules scanner if any rules found
59		customRules, err := config.LoadAllRules(o.cfg)
60		if err != nil {
61			o.bus.Publish(eventbus.NewEvent(eventbus.EventLogMessage, eventbus.LogMessageData{
62				Level: "warn", Message: fmt.Sprintf("Failed to load custom rules: %v", err),
63			}))
64		} else if len(customRules) > 0 {
65			scanners = append(scanners, rulesscanner.New(customRules))
66			o.bus.Publish(eventbus.NewEvent(eventbus.EventLogMessage, eventbus.LogMessageData{
67				Level: "info", Message: fmt.Sprintf("Loaded %d custom rule(s)", len(customRules)),
68			}))
69		}
70	
71		// Filter scanners based on config enable/disable lists
72		scanners = o.filterScanners(scanners)
73	
74		o.bus.Publish(eventbus.NewEvent(eventbus.EventScanStarted, eventbus.ScanStartedData{
75			ProjectPath:  o.target,
76			ProjectName:  o.target,
77			ScannerCount: len(scanners),
78		}))
79	
80		// --- Stage 1: Provider ---
81		o.stageStart(models.StageProvider)
82	
83		var src provider.SourceProvider
84		if provider.IsGitURL(o.target) {
85			src = provider.NewGitProvider(o.cfg.Providers.GitDepth)
86			o.bus.Publish(eventbus.NewEvent(eventbus.EventLogMessage, eventbus.LogMessageData{
87				Level: "info", Message: fmt.Sprintf("Cloning %s ...", o.target),
88			}))
89		} else {
90			src = provider.NewLocalProvider()
91		}
92	
93		result, err := src.Acquire(ctx, o.target)
94		if err != nil {
95			return o.fail(fmt.Errorf("provider: %w", err))
96		}
97		defer src.Cleanup()
98	
99		if !result.IsLaravel {
100			o.bus.Publish(eventbus.NewEvent(eventbus.EventLogMessage, eventbus.LogMessageData{
101				Level: "warn", Message: "Path does not appear to be a Laravel project",
102			}))
103		}
104	
105		o.stageComplete(models.StageProvider)
106	
107		// --- Stage 2: Resolvers ---
108		o.stageStart(models.StageResolvers)
109	
110		pc := &models.ProjectContext{}
111		resolvers := []resolver.ContextResolver{
112			resolver.NewFrameworkResolver(),
113			resolver.NewPackageResolver(),
114		}
115	
116		for _, r := range resolvers {
117			if err := r.Resolve(ctx, result.RootPath, pc); err != nil {
118				o.bus.Publish(eventbus.NewEvent(eventbus.EventLogMessage, eventbus.LogMessageData{
119					Level: "error", Message: fmt.Sprintf("Resolver %s failed: %v", r.Name(), err),
120				}))
121			}
122		}
123	
124		// Emit resolved project context to TUI
125		o.bus.Publish(eventbus.NewEvent(eventbus.EventContextResolved, eventbus.ContextResolvedData{
126			ProjectName:    pc.ProjectName,
127			LaravelVersion: pc.LaravelVersion,
128			PHPVersion:     pc.PHPVersion,
129			FrameworkType:  pc.FrameworkType,
130			PackageCount:   len(pc.InstalledPackages),
131		}))
132	
133		o.stageComplete(models.StageResolvers)
134	
135		// --- Stage 3: Scanners ---
136		o.stageStart(models.StageScanners)
137	
138		// Register all scanners
139		for _, sc := range scanners {
140			o.bus.Publish(eventbus.NewEvent(eventbus.EventScannerRegistered, eventbus.ScannerRegisteredData{
141				Name:        sc.Name(),
142				Description: sc.Description(),
143			}))
144		}
145	
146		var allFindings []models.Finding
147		scannersRun := make([]string, 0, len(scanners))
148		scannerErrors := make(map[string]string)
149	
150		for _, sc := range scanners {
151			if o.isScannerDisabled(sc.Name()) {
152				o.bus.Publish(eventbus.NewEvent(eventbus.EventScannerSkipped, eventbus.ScannerSkippedData{
153					Name: sc.Name(), Reason: "disabled in config",
154				}))
155				continue
156			}
157	
158			o.bus.Publish(eventbus.NewEvent(eventbus.EventScannerStarted, eventbus.ScannerStartedData{
159				Name: sc.Name(),
160			}))
161	
162			emit := func(f models.Finding) {
163				o.bus.Publish(eventbus.NewEvent(eventbus.EventFindingDiscovered, eventbus.FindingDiscoveredData{
164					Finding: f,
165				}))
166			}
167	
168			findings, err := sc.Scan(ctx, *pc, emit)
169			if err != nil {
170				scannerErrors[sc.Name()] = err.Error()
171				o.bus.Publish(eventbus.NewEvent(eventbus.EventScannerFailed, eventbus.ScannerFailedData{
172					Name: sc.Name(), Error: err,
173				}))
174				continue
175			}
176	
177			allFindings = append(allFindings, findings...)
178			scannersRun = append(scannersRun, sc.Name())
179	
180			o.bus.Publish(eventbus.NewEvent(eventbus.EventScannerCompleted, eventbus.ScannerCompletedData{
181				Name:         sc.Name(),
182				FindingCount: len(findings),
183			}))
184		}
185	
186		o.stageComplete(models.StageScanners)
187	
188		// --- Stage 4: Post-Process ---
189		o.stageStart(models.StagePostProcess)
190		allFindings = deduplicate(allFindings)
191		allFindings = filterBySeverity(allFindings, models.ParseSeverity(o.cfg.Severity))
192	
193		// Apply baseline filtering
194		if o.baseline != nil {
195			var suppressed int
196			allFindings, suppressed = o.baseline.Filter(allFindings)
197			if suppressed > 0 {
198				o.bus.Publish(eventbus.NewEvent(eventbus.EventLogMessage, eventbus.LogMessageData{
199					Level: "info", Message: fmt.Sprintf("%d findings suppressed by baseline", suppressed),
200				}))
201			}
202		}
203	
204		o.stageComplete(models.StagePostProcess)
205	
206		// --- Stage 5: Report ---
207		o.stageStart(models.StageReport)
208	
209		endTime := time.Now()
210		report := &models.ScanReport{
211			ProjectContext: *pc,
212			Findings:       allFindings,
213			StartedAt:      startTime,
214			CompletedAt:    endTime,
215			Duration:       endTime.Sub(startTime),
216			ScannersRun:    scannersRun,
217			ScannerErrors:  scannerErrors,
218		}
219	
220		reporters := o.buildReporters()
221		for _, rep := range reporters {
222			if err := rep.Generate(ctx, report); err != nil {
223				o.bus.Publish(eventbus.NewEvent(eventbus.EventLogMessage, eventbus.LogMessageData{
224					Level: "error", Message: fmt.Sprintf("%s reporter failed: %v", rep.Name(), err),
225				}))
226			} else {
227				o.bus.Publish(eventbus.NewEvent(eventbus.EventLogMessage, eventbus.LogMessageData{
228					Level: "info", Message: fmt.Sprintf("Report written to ward-report.%s", rep.Format()),
229				}))
230			}
231		}
232	
233		// Compare with last scan and save to store
234		diff, _ := store.CompareLast(report)
235		if diff != nil {
236			if len(diff.NewFindings) > 0 || len(diff.ResolvedFindings) > 0 {
237				o.bus.Publish(eventbus.NewEvent(eventbus.EventLogMessage, eventbus.LogMessageData{
238					Level: "info", Message: fmt.Sprintf("vs last scan: %d new, %d resolved (%d→%d)",
239						len(diff.NewFindings), len(diff.ResolvedFindings), diff.TotalBefore, diff.TotalAfter),
240				}))
241			}
242		}
243	
244		if _, err := store.Save(report); err != nil {
245			o.bus.Publish(eventbus.NewEvent(eventbus.EventLogMessage, eventbus.LogMessageData{
246				Level: "warn", Message: fmt.Sprintf("Failed to save scan history: %v", err),
247			}))
248		}
249	
250		o.stageComplete(models.StageReport)
251	
252		// Save baseline if requested
253		if o.baselinePath != "" {
254			if err := baseline.Save(o.baselinePath, allFindings); err != nil {
255				o.bus.Publish(eventbus.NewEvent(eventbus.EventLogMessage, eventbus.LogMessageData{
256					Level: "warn", Message: fmt.Sprintf("Failed to save baseline: %v", err),
257				}))
258			} else {
259				o.bus.Publish(eventbus.NewEvent(eventbus.EventLogMessage, eventbus.LogMessageData{
260					Level: "info", Message: fmt.Sprintf("Baseline saved to %s (%d findings)", o.baselinePath, len(allFindings)),
261				}))
262			}
263		}
264	
265		// --- Done ---
266		o.bus.Publish(eventbus.NewEvent(eventbus.EventScanCompleted, eventbus.ScanCompletedData{
267			Report: report,
268		}))
269	
270		return nil
271	}
272	
273	func (o *Orchestrator) stageStart(stage models.PipelineStage) {
274		o.bus.Publish(eventbus.NewEvent(eventbus.EventStageStarted, eventbus.StageStartedData{Stage: stage}))
275	}
276	
277	func (o *Orchestrator) stageComplete(stage models.PipelineStage) {
278		o.bus.Publish(eventbus.NewEvent(eventbus.EventStageCompleted, eventbus.StageCompletedData{Stage: stage}))
279	}
280	
281	func (o *Orchestrator) fail(err error) error {
282		o.bus.Publish(eventbus.NewEvent(eventbus.EventScanFailed, eventbus.ScanFailedData{Error: err}))
283		return err
284	}
285	
286	func (o *Orchestrator) isScannerDisabled(name string) bool {
287		for _, d := range o.cfg.Scanners.Disable {
288			if d == name {
289				return true
290			}
291		}
292		return false
293	}
294	
295	func filterBySeverity(findings []models.Finding, minSeverity models.Severity) []models.Finding {
296		if minSeverity == models.SeverityInfo {
297			return findings
298		}
299		result := make([]models.Finding, 0, len(findings))
300		for _, f := range findings {
301			if f.Severity >= minSeverity {
302				result = append(result, f)
303			}
304		}
305		return result
306	}
307	
308	func (o *Orchestrator) buildReporters() []reporter.Reporter {
309		outDir := o.cfg.Output.Dir
310		formats := o.cfg.Output.Formats
311	
312		// Default to JSON if no formats specified
313		if len(formats) == 0 {
314			formats = []string{"json"}
315		}
316	
317		var reporters []reporter.Reporter
318		seen := make(map[string]bool)
319	
320		for _, f := range formats {
321			if seen[f] {
322				continue
323			}
324			seen[f] = true
325	
326			switch f {
327			case "json":
328				reporters = append(reporters, reporter.NewJSONReporter(outDir))
329			case "sarif":
330				reporters = append(reporters, reporter.NewSARIFReporter(outDir, o.version))
331			case "html":
332				reporters = append(reporters, reporter.NewHTMLReporter(outDir, o.version))
333			case "markdown", "md":
334				reporters = append(reporters, reporter.NewMarkdownReporter(outDir, o.version))
335			case "terminal":
336				// terminal output is handled by the headless/TUI path, not a file reporter
337				continue
338			}
339		}
340	
341		// Always generate JSON as baseline
342		if !seen["json"] {
343			reporters = append(reporters, reporter.NewJSONReporter(outDir))
344		}
345	
346		return reporters
347	}
348	
349	func deduplicate(findings []models.Finding) []models.Finding {
350		seen := make(map[string]bool)
351		result := make([]models.Finding, 0, len(findings))
352		for _, f := range findings {
353			key := f.ID + "|" + f.File + "|" + fmt.Sprintf("%d", f.Line)
354			if seen[key] {
355				continue
356			}
357			seen[key] = true
358			result = append(result, f)
359		}
360		return result
361	}
362	
363	// filterScanners applies the config enable/disable lists.
364	func (o *Orchestrator) filterScanners(scanners []models.Scanner) []models.Scanner {
365		enable := o.cfg.Scanners.Enable
366		disable := o.cfg.Scanners.Disable
367	
368		if len(enable) == 0 && len(disable) == 0 {
369			return scanners
370		}
371	
372		enableSet := make(map[string]bool, len(enable))
373		for _, name := range enable {
374			enableSet[strings.ToLower(name)] = true
375		}
376	
377		disableSet := make(map[string]bool, len(disable))
378		for _, name := range disable {
379			disableSet[strings.ToLower(name)] = true
380		}
381	
382		var filtered []models.Scanner
383		for _, s := range scanners {
384			name := strings.ToLower(s.Name())
385	
386			// If enable list is set, only run scanners in that list
387			if len(enableSet) > 0 && !enableSet[name] {
388				o.bus.Publish(eventbus.NewEvent(eventbus.EventLogMessage, eventbus.LogMessageData{
389					Level: "info", Message: fmt.Sprintf("Skipping %s (not in enable list)", s.Name()),
390				}))
391				continue
392			}
393	
394			// If disable list is set, skip scanners in that list
395			if disableSet[name] {
396				o.bus.Publish(eventbus.NewEvent(eventbus.EventLogMessage, eventbus.LogMessageData{
397					Level: "info", Message: fmt.Sprintf("Skipping %s (disabled)", s.Name()),
398				}))
399				continue
400			}
401	
402			filtered = append(filtered, s)
403		}
404	
405		return filtered
406	}
