1	package dependency
2	
3	import (
4		"bytes"
5		"context"
6		"encoding/json"
7		"fmt"
8		"io"
9		"net/http"
10		"strings"
11		"time"
12	
13		"github.com/eljakani/ward/internal/models"
14	)
15	
16	const (
17		osvQueryURL = "https://api.osv.dev/v1/query"
18		osvBatchURL = "https://api.osv.dev/v1/querybatch"
19		batchSize   = 100
20		httpTimeout = 30 * time.Second
21	)
22	
23	// Scanner checks installed packages against the OSV.dev vulnerability database.
24	type Scanner struct {
25		client *http.Client
26	}
27	
28	func New() *Scanner {
29		return &Scanner{
30			client: &http.Client{Timeout: httpTimeout},
31		}
32	}
33	
34	func (s *Scanner) Name() string        { return "dependency-scanner" }
35	func (s *Scanner) Description() string { return "Live CVE checks via OSV.dev (Packagist SBOM)" }
36	
37	func (s *Scanner) Scan(ctx context.Context, project models.ProjectContext, emit func(models.Finding)) ([]models.Finding, error) {
38		if len(project.InstalledPackages) == 0 {
39			return nil, nil
40		}
41	
42		// Step 1: Batch query to find which packages have known vulnerabilities
43		vulnPackages, err := s.batchQuery(ctx, project.InstalledPackages)
44		if err != nil {
45			return nil, fmt.Errorf("querying OSV.dev: %w", err)
46		}
47	
48		if len(vulnPackages) == 0 {
49			return nil, nil
50		}
51	
52		// Step 2: Fetch full vulnerability details for affected packages
53		var findings []models.Finding
54	
55		for _, vp := range vulnPackages {
56			vulns, err := s.queryPackage(ctx, vp.name, vp.version)
57			if err != nil {
58				continue // skip on error, don't fail the whole scan
59			}
60	
61			for _, vuln := range vulns {
62				f := vulnToFinding(s.Name(), vp.name, vp.version, vuln)
63				findings = append(findings, f)
64				emit(f)
65			}
66		}
67	
68		return findings, nil
69	}
70	
71	type vulnPackage struct {
72		name    string
73		version string
74	}
75	
76	// batchQuery sends all packages to OSV.dev batch endpoint and returns those with vulnerabilities.
77	func (s *Scanner) batchQuery(ctx context.Context, packages map[string]string) ([]vulnPackage, error) {
78		// Build list of packages
79		type query struct {
80			Package struct {
81				Name      string `json:"name"`
82				Ecosystem string `json:"ecosystem"`
83			} `json:"package"`
84			Version string `json:"version"`
85		}
86	
87		var allQueries []query
88		var packageOrder []vulnPackage // preserve order for matching results
89	
90		for name, version := range packages {
91			version = normalizeVersion(version)
92			if version == "" {
93				continue
94			}
95			q := query{Version: version}
96			q.Package.Name = name
97			q.Package.Ecosystem = "Packagist"
98			allQueries = append(allQueries, q)
99			packageOrder = append(packageOrder, vulnPackage{name: name, version: version})
100		}
101	
102		// Send in batches
103		var affected []vulnPackage
104	
105		for i := 0; i < len(allQueries); i += batchSize {
106			end := i + batchSize
107			if end > len(allQueries) {
108				end = len(allQueries)
109			}
110	
111			batch := allQueries[i:end]
112			batchOrder := packageOrder[i:end]
113	
114			body, _ := json.Marshal(map[string]any{"queries": batch})
115			req, err := http.NewRequestWithContext(ctx, "POST", osvBatchURL, bytes.NewReader(body))
116			if err != nil {
117				return nil, err
118			}
119			req.Header.Set("Content-Type", "application/json")
120	
121			resp, err := s.client.Do(req)
122			if err != nil {
123				return nil, err
124			}
125	
126			var result struct {
127				Results []struct {
128					Vulns []struct {
129						ID string `json:"id"`
130					} `json:"vulns"`
131				} `json:"results"`
132			}
133	
134			data, _ := io.ReadAll(resp.Body)
135			resp.Body.Close()
136	
137			if resp.StatusCode != 200 {
138				return nil, fmt.Errorf("OSV.dev returned status %d", resp.StatusCode)
139			}
140	
141			if err := json.Unmarshal(data, &result); err != nil {
142				return nil, fmt.Errorf("parsing OSV.dev response: %w", err)
143			}
144	
145			for j, r := range result.Results {
146				if len(r.Vulns) > 0 && j < len(batchOrder) {
147					affected = append(affected, batchOrder[j])
148				}
149			}
150		}
151	
152		return affected, nil
153	}
154	
155	// queryPackage fetches full vulnerability details for a single package+version.
156	func (s *Scanner) queryPackage(ctx context.Context, name, version string) ([]osvVuln, error) {
157		body, _ := json.Marshal(map[string]any{
158			"package": map[string]string{
159				"name":      name,
160				"ecosystem": "Packagist",
161			},
162			"version": version,
163		})
164	
165		req, err := http.NewRequestWithContext(ctx, "POST", osvQueryURL, bytes.NewReader(body))
166		if err != nil {
167			return nil, err
168		}
169		req.Header.Set("Content-Type", "application/json")
170	
171		resp, err := s.client.Do(req)
172		if err != nil {
173			return nil, err
174		}
175		defer resp.Body.Close()
176	
177		if resp.StatusCode != 200 {
178			return nil, fmt.Errorf("OSV.dev returned status %d", resp.StatusCode)
179		}
180	
181		var result struct {
182			Vulns []osvVuln `json:"vulns"`
183		}
184	
185		data, _ := io.ReadAll(resp.Body)
186		if err := json.Unmarshal(data, &result); err != nil {
187			return nil, err
188		}
189	
190		return result.Vulns, nil
191	}
192	
193	// OSV.dev response structures
194	
195	type osvVuln struct {
196		ID               string           `json:"id"`
197		Summary          string           `json:"summary"`
198		Details          string           `json:"details"`
199		Aliases          []string         `json:"aliases"`
200		References       []osvReference   `json:"references"`
201		Affected         []osvAffected    `json:"affected"`
202		DatabaseSpecific osvDBSpecific    `json:"database_specific"`
203	}
204	
205	type osvReference struct {
206		Type string `json:"type"`
207		URL  string `json:"url"`
208	}
209	
210	type osvAffected struct {
211		Package struct {
212			Name      string `json:"name"`
213			Ecosystem string `json:"ecosystem"`
214		} `json:"package"`
215		Ranges []osvRange `json:"ranges"`
216	}
217	
218	type osvRange struct {
219		Type   string     `json:"type"`
220		Events []osvEvent `json:"events"`
221	}
222	
223	type osvEvent struct {
224		Introduced string `json:"introduced,omitempty"`
225		Fixed      string `json:"fixed,omitempty"`
226	}
227	
228	type osvDBSpecific struct {
229		Severity string `json:"severity"`
230		CWEIDs   []string `json:"cwe_ids"`
231	}
232	
233	// vulnToFinding converts an OSV vulnerability to a Ward finding.
234	func vulnToFinding(scanner, pkgName, pkgVersion string, vuln osvVuln) models.Finding {
235		// Extract CVE ID from aliases
236		cveID := vuln.ID
237		for _, alias := range vuln.Aliases {
238			if strings.HasPrefix(alias, "CVE-") {
239				cveID = alias
240				break
241			}
242		}
243	
244		// Determine severity
245		severity := parseSeverity(vuln.DatabaseSpecific.Severity)
246	
247		// Extract fixed version from affected ranges
