197			lower := strings.ToLower(val)
198			if lower == "null" || lower == "secret" || lower == "password" || lower == "your_password_here" || lower == "changeme" {
199				continue
200			}
201			// If it's longer than 6 chars and not a placeholder, flag it
202			if len(val) > 6 {
