204					ID:          "ENV-008",
205					Title:       fmt.Sprintf("Potential real credential in .env.example: %s", key),
206					Description: fmt.Sprintf("The .env.example file contains a value for %s that doesn't look like a placeholder. This file is typically committed to version control and should only contain example/placeholder values.", key),
