224		f, err := os.Open(path)
225		if err != nil {
226			return nil, err
227		}
228		defer f.Close()
229	
230		vars := make(map[string]string)
231		scanner := bufio.NewScanner(f)
232		for scanner.Scan() {
233			line := strings.TrimSpace(scanner.Text())
234			if line == "" || strings.HasPrefix(line, "#") {
235				continue
236			}
237			parts := strings.SplitN(line, "=", 2)
238			if len(parts) != 2 {
239				continue
240			}
241			key := strings.TrimSpace(parts[0])
242			val := strings.TrimSpace(parts[1])
243			val = strings.Trim(val, `"'`)
244			vars[key] = val
245		}
246		return vars, scanner.Err()
247	}
248	
249	func findLine(path, key string) int {
250		f, err := os.Open(path)
251		if err != nil {
252			return 0
253		}
254		defer f.Close()
255	
256		lineNum := 0
257		scanner := bufio.NewScanner(f)
258		for scanner.Scan() {
259			lineNum++
260			if strings.HasPrefix(strings.TrimSpace(scanner.Text()), key+"=") ||
261				strings.HasPrefix(strings.TrimSpace(scanner.Text()), key+" =") {
262				return lineNum
263			}
264		}
265		return 0
266	}
267	
268	func isWeakKey(val string) bool {
269		lower := strings.ToLower(val)
270		// All zeros/A's base64 key
271		if strings.HasPrefix(lower, "base64:aaaaaaa") {
272			return true
273		}
274		// Common test keys
275		if lower == "somerandostrng" || lower == "somerandomstring" {
276			return true
277		}
278		// Too short after base64: prefix
279		if strings.HasPrefix(val, "base64:") && len(val) < 20 {
280			return true
281		}
282		return false
283	}
284	
285	func maskValue(val string) string {
286		if len(val) <= 4 {
287			return "****"
288		}
289		return val[:2] + strings.Repeat("*", len(val)-4) + val[len(val)-2:]
290	}
