package provider

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

// GitProvider clones a remote git repository and provides it for scanning.
type GitProvider struct {
	Depth   int
	tempDir string
}

func NewGitProvider(depth int) *GitProvider {
	if depth <= 0 {
		depth = 1
	}
	return &GitProvider{Depth: depth}
}

func (p *GitProvider) Acquire(ctx context.Context, repoURL string) (*SourceResult, error) {
	tmpDir, err := os.MkdirTemp("", "ward-scan-*")
	if err != nil {
		return nil, fmt.Errorf("creating temp directory: %w", err)
	}
	p.tempDir = tmpDir

	args := []string{"clone"}
	if p.Depth > 0 {
		args = append(args, "--depth", fmt.Sprintf("%d", p.Depth))
	}
	args = append(args, repoURL, tmpDir)

	cmd := exec.CommandContext(ctx, "git", args...)
	// Capture output instead of writing to os.Stderr, which corrupts the TUI
	output, err := cmd.CombinedOutput()
	if err != nil {
		_ = os.RemoveAll(tmpDir)
		return nil, fmt.Errorf("git clone failed: %w\n%s", err, string(output))
	}

	result := &SourceResult{
		RootPath:  tmpDir,
		IsLaravel: false,
		HasGit:    true,
	}

	// Check for artisan file
	if _, err := os.Stat(filepath.Join(tmpDir, "artisan")); err == nil {
		result.IsLaravel = true
		return result, nil
	}

	// Fall back to checking composer.json
	data, err := os.ReadFile(filepath.Join(tmpDir, "composer.json"))
	if err != nil {
		return result, nil
	}

	var composer struct {
		Require map[string]string `json:"require"`
	}
	if err := json.Unmarshal(data, &composer); err != nil {
		return result, nil
	}

	if _, ok := composer.Require["laravel/framework"]; ok {
		result.IsLaravel = true
	}

	return result, nil
}

func (p *GitProvider) Cleanup() error {
	if p.tempDir != "" {
		return os.RemoveAll(p.tempDir)
	}
	return nil
}

// IsGitURL checks if the given path looks like a git URL.
func IsGitURL(path string) bool {
	return strings.HasPrefix(path, "http://") ||
		strings.HasPrefix(path, "https://") ||
		strings.HasPrefix(path, "git@") ||
		strings.HasPrefix(path, "ssh://") ||
		strings.HasSuffix(path, ".git")
}

package models

import "strings"

// Severity represents the severity level of a security finding.
type Severity int

const (
	SeverityInfo Severity = iota
	SeverityLow
	SeverityMedium
	SeverityHigh
	SeverityCritical
)

func (s Severity) String() string {
	switch s {
	case SeverityInfo:
		return "Info"
	case SeverityLow:
		return "Low"
	case SeverityMedium:
		return "Medium"
	case SeverityHigh:
		return "High"
	case SeverityCritical:
		return "Critical"
	default:
		return "Unknown"
	}
}

// Weight returns a numeric weight for sorting (higher = more severe).
func (s Severity) Weight() int {
	return int(s)
}

// ParseSeverity converts a string to a Severity level.
func ParseSeverity(s string) Severity {
	switch strings.ToLower(s) {
	case "critical":
		return SeverityCritical
	case "high":
		return SeverityHigh
	case "medium":
		return SeverityMedium
	case "low":
		return SeverityLow
	default:
		return SeverityInfo
	}
}

// AllSeverities returns all severity levels in ascending order.
func AllSeverities() []Severity {
	return []Severity{
		SeverityInfo,
		SeverityLow,
		SeverityMedium,
		SeverityHigh,
		SeverityCritical,
	}
}

