1	// Package web runs HTTP exposure checks against deployed web roots.
2	//
3	// Unlike the filesystem rule engine these checks are stateful: each host is
4	// probed once with a random nonce URL to establish a soft-404 baseline, and
5	// responses are normalized before comparison so SPA catch-all fallbacks and
6	// templated error pages cannot produce false positives. The matching logic
7	// for exposed-git-config lives here on purpose — the generic YAML matchers
8	// cannot express it.
9	package web
10	
11	import (
12		"bufio"
13		"bytes"
14		"context"
15		"crypto/rand"
16		"encoding/hex"
17		"fmt"
18		"io"
19		"net/http"
20		"net/url"
21		"regexp"
22		"strconv"
23		"strings"
24		"time"
25	
26		"github.com/eljakani/ward/internal/config"
27		"github.com/eljakani/ward/internal/models"
28	)
29	
30	const (
31		// ExposedGitConfigRuleID is the YAML rule served by this scanner.
32		ExposedGitConfigRuleID = "exposed-git-config"
33	
34		// ScannerName is the orchestrator-facing scanner identifier.
35		ScannerName = "web-exposure-scanner"
36	
37		gitConfigPath = "/.git/config"
38		probePathFmt  = "/.git/ward-%s.probe"
39	
40		defaultTimeout = 10 * time.Second
41		// maxBodyBytes caps every response body so a large or streamed reply
42		// cannot blow up the scan.
43		maxBodyBytes = 1 << 20 // 1 MiB
44	
45		userAgent = "ward-security-scanner"
46	)
47	
48	var (
49		// Both patterns must match on separate lines of the raw body. Real git
50		// config files tab-indent their key lines, so the line anchors tolerate
51		// leading/trailing whitespace while still requiring a full-line match.
52		coreSectionRE = regexp.MustCompile(`(?m)^\s*\[core\]\s*$`)
53		versionRE     = regexp.MustCompile(`(?m)^\s*repositoryformatversion\s*=\s*\d+\s*$`)
54	
55		htmlTagRE = regexp.MustCompile(`(?is)<\s*(html|!doctype\s+html|head|body)\b`)
56		// Catches login forms even in HTML fragments without a doctype.
57		loginRE = regexp.MustCompile(`(?is)<input[^>]+type\s*=\s*["']?password["']?|<form[^>]+(login|signin|sign-in)`)
58		// Matches the nonce probe path regardless of the generated nonce.
59		probePathRE  = regexp.MustCompile(`(?i)/\.git/ward-[a-z0-9]*\.probe`)
60		whitespaceRE = regexp.MustCompile(`\s+`)
61	)
62	
63	// httpResponse is the trimmed, size-capped view of an HTTP reply.
64	type httpResponse struct {
65		status int
66		header http.Header
67		body   []byte
68	}
69	
70	// Scanner evaluates HTTP exposure rules against a fixed set of origins.
71	type Scanner struct {
72		rule    *config.RuleDefinition
73		origins []string
74		client  *http.Client
75		nonce   string
76	
77		// probeCache holds the soft-404 baseline per host for the lifetime of
78		// one scan; a host is probed at most once.
79		probeCache map[string]*probeResult
80	}
81	
82	type probeResult struct {
83		resp *httpResponse
84		err  error
85	}
86	
87	// Option customizes a Scanner, mainly for tests.
88	type Option func(*Scanner)
89	
90	// WithTimeout overrides the per-request HTTP timeout.
91	func WithTimeout(d time.Duration) Option {
92		return func(s *Scanner) {
93			if d > 0 {
94				s.client.Timeout = d
95			}
96		}
97	}
98	
99	// WithHTTPClient swaps the HTTP client (tests use it to pin behavior).
100	func WithHTTPClient(c *http.Client) Option {
101		return func(s *Scanner) {
102			if c != nil {
103				s.client = c
104			}
105		}
106	}
107	
108	// WithNonce pins the probe nonce instead of generating a random one.
109	func WithNonce(nonce string) Option {
110		return func(s *Scanner) {
111			if nonce != "" {
112				s.nonce = nonce
113			}
114		}
115	}
116	
117	// New creates a web exposure Scanner. rule carries the finding metadata
118	// loaded from exposure.yaml; origins are web roots and are always reduced to
119	// scheme+host before any path is appended.
120	func New(rule *config.RuleDefinition, origins []string, opts ...Option) *Scanner {
121		s := &Scanner{
122			rule:       rule,
123			origins:    origins,
124			client:     newHTTPClient(defaultTimeout),
125			nonce:      newNonce(),
126			probeCache: make(map[string]*probeResult),
127		}
128		for _, opt := range opts {
129			opt(s)
130		}
131		return s
132	}
133	
134	func newHTTPClient(timeout time.Duration) *http.Client {
135		return &http.Client{
136			Timeout: timeout,
137			// Never follow redirects: a 3xx (login bounce, http->https, ...) is
138			// itself a signal that the raw file is not directly readable.
139			CheckRedirect: func(req *http.Request, via []*http.Request) error {
140				return http.ErrUseLastResponse
141			},
142		}
143	}
144	
145	func (s *Scanner) Name() string { return ScannerName }
146	
147	func (s *Scanner) Description() string {
148		return "HTTP exposure checks against deployed web roots"
149	}
150	
151	// Scan runs every enabled HTTP exposure check against each configured origin.
152	// Network failures on a single origin are skipped rather than failing the
153	// whole (otherwise local) scan.
154	func (s *Scanner) Scan(ctx context.Context, _ models.ProjectContext, emit func(models.Finding)) ([]models.Finding, error) {
155		if s.rule == nil || !s.rule.Enabled {
156			return nil, nil
157		}
158	
159		var findings []models.Finding
160		seen := make(map[string]bool)
161	
162		for _, origin := range s.origins {
163			origin = strings.TrimSpace(origin)
164			if origin == "" || seen[origin] {
165				continue
166			}
167			seen[origin] = true
168	
169			finding, err := s.checkGitConfig(ctx, origin)
170			if err != nil || finding == nil {
171				continue
172			}
173			findings = append(findings, *finding)
174			emit(*finding)
175		}
176	
177		return findings, nil
178	}
179	
180	// checkGitConfig implements the dedicated exposed-git-config decision:
181	// strict raw-body match first, soft-404 suppression second, with probe
182	// failures never downgrading a strict raw hit.
183	func (s *Scanner) checkGitConfig(ctx context.Context, origin string) (*models.Finding, error) {
184		realURL := joinOriginPath(origin, gitConfigPath)
185	
186		real, err := s.doGet(ctx, realURL)
187		if err != nil {
188			return nil, err
189		}
190	
191		// A 200 alone is never sufficient.
192		if real.status != http.StatusOK {
193			return nil, nil
194		}
195	
196		switch evaluateGitConfigBody(real) {
197		case bodyNoMatch, bodyHTML:
198			// HTML pages (SPA shells, login screens, path-echoing error pages)
199			// are rejected outright — even if the probe later fails.
200			return nil, nil
201		}
202	
203		// Soft-404 baseline, cached per host for this scan. Only an actual
204		// probe response can suppress; transport errors must not swallow the
205		// strict raw match above.
206		probe, probeErr := s.probeHost(ctx, origin)
207		if probeErr == nil && probe != nil {
208			if s.normalize(probe.body) == s.normalize(real.body) {
209				return nil, nil
210			}
211		}
212	
213		return s.buildFinding(realURL, real), nil
214	}
215	
216	type bodyVerdict int
217	
218	const (
219		bodyNoMatch bodyVerdict = iota
220		bodyHTML
221		bodyMatch
222	)
223	
224	// evaluateGitConfigBody applies the strict content checks. Both required
225	// lines must be present, and the reply must not be an HTML/login document.
226	func evaluateGitConfigBody(resp *httpResponse) bodyVerdict {
227		body := resp.body
228		if len(bytes.TrimSpace(body)) == 0 {
229			return bodyNoMatch
230		}
231		if looksLikeHTML(resp) {
232			return bodyHTML
233		}
234		if !coreSectionRE.Match(body) || !versionRE.Match(body) {
235			return bodyNoMatch
236		}
237		return bodyMatch
238	}
239	
240	func looksLikeHTML(resp *httpResponse) bool {
241		if ct := strings.ToLower(resp.header.Get("Content-Type")); strings.Contains(ct, "html") {
242			return true
243		}
244		body := resp.body
245		if head := len(body); head > 512 {
246			body = body[:512]
247		}
248		if htmlTagRE.Match(body) {
249			return true
250		}
251		// Password fields can appear in an HTML fragment without doctype/head.
252		return loginRE.Match(resp.body)
253	}
254	
255	// probeHost fetches the nonce probe URL once per host and caches the outcome.
256	func (s *Scanner) probeHost(ctx context.Context, origin string) (*httpResponse, error) {
257		key := hostKey(origin)
258		if cached, ok := s.probeCache[key]; ok {
259			return cached.resp, cached.err
260		}
261	
262		probeURL := joinOriginPath(origin, fmt.Sprintf(probePathFmt, s.nonce))
263		resp, err := s.doGet(ctx, probeURL)
264		s.probeCache[key] = &probeResult{resp: resp, err: err}
265		return resp, err
266	}
267	
268	// doGet issues a GET with no redirect following and a capped response body.
269	func (s *Scanner) doGet(ctx context.Context, rawurl string) (*httpResponse, error) {
270		req, err := http.NewRequestWithContext(ctx, http.MethodGet, rawurl, nil)
271		if err != nil {
272			return nil, err
273		}
274		req.Header.Set("User-Agent", userAgent)
275		req.Header.Set("Accept", "*/*")
276	
277		resp, err := s.client.Do(req)
278		if err != nil {
279			return nil, err
280		}
281		defer resp.Body.Close()
282	
283		body, err := io.ReadAll(io.LimitReader(resp.Body, maxBodyBytes))
284		if err != nil {
285			return nil, err
286		}
287	
288		return &httpResponse{
289			status: resp.StatusCode,
290			header: resp.Header.Clone(),
291			body:   body,
292		}, nil
293	}
294	
295	// normalize makes two templated responses comparable: lower-casing, removing
296	// the request paths/nonce that error pages tend to echo, and collapsing
297	// whitespace so indentation and line-ending differences disappear.
298	func (s *Scanner) normalize(body []byte) string {
299		text := strings.ToLower(string(body))
300		text = probePathRE.ReplaceAllString(text, "")
301		text = strings.ReplaceAll(text, s.nonce, "")
302		text = strings.ReplaceAll(text, strings.ToLower(gitConfigPath), "")
303		text = whitespaceRE.ReplaceAllString(text, " ")
304		return strings.TrimSpace(text)
305	}
306	
307	func (s *Scanner) buildFinding(rawurl string, resp *httpResponse) *models.Finding {
308		r := s.rule
309		return &models.Finding{
310			ID:          r.ID,
311			Title:       r.Title,
312			Description: r.Description,
313			Severity:    models.ParseSeverity(r.Severity),
314			Category:    r.Category,
315			Scanner:     s.Name(),
316			File:        rawurl,
317			CodeSnippet: snippetFromBody(resp.body),
318			Remediation: r.Remediation,
319			References:  r.References,
320		}
321	}
322	
323	// snippetFromBody extracts the matching lines for the report, capped.
324	func snippetFromBody(body []byte) string {
325		var lines []string
326		sc := bufio.NewScanner(bytes.NewReader(body))
327		for sc.Scan() {
328			line := strings.TrimSpace(sc.Text())
329			if coreSectionRE.MatchString(line) || versionRE.MatchString(line) {
330				lines = append(lines, line)
331				if len(lines) >= 4 {
332					break
333				}
334			}
335		}
336		return strings.Join(lines, "\n")
337	}
338	
339	// OriginsFromTarget builds the de-duplicated probe list. Configured origins
340	// come first; when the scan target is itself an http(s) URL its origin is
341	// appended, along with the opposite-scheme variant so a scheme mismatch does
342	// not silently skip the check. Non-HTTP targets (local paths, git@, ssh)
343	// contribute nothing.
344	func OriginsFromTarget(target string, extra []string) []string {
345		var out []string
346		seen := make(map[string]bool)
347	
348		add := func(raw string) {
349			origin, ok := originOf(raw)
350			if !ok || seen[origin] {
351				return
352			}
353			seen[origin] = true
354			out = append(out, origin)
355		}
356	
357		for _, o := range extra {
358			add(o)
359		}
360	
361		if u, err := url.Parse(strings.TrimSpace(target)); err == nil &&
362			(u.Scheme == "http" || u.Scheme == "https") && u.Host != "" {
363			add(target)
364	
365			alt := *u
366			if u.Scheme == "http" {
367				alt.Scheme = "https"
368			} else {
369				alt.Scheme = "http"
370			}
371			add(alt.String())
372		}
373	
374		return out
375	}
376	
377	// originOf reduces an arbitrary URL to its scheme+host root, rejecting
378	// non-http(s) input. Business base paths are deliberately discarded so
379	// requests are built against the origin, never behind an app base path.
380	func originOf(raw string) (string, bool) {
381		u, err := url.Parse(strings.TrimSpace(raw))
382		if err != nil || u.Host == "" || (u.Scheme != "http" && u.Scheme != "https") {
383			return "", false
384		}
385		u.Path = ""
386		u.RawPath = ""
387		u.RawQuery = ""
388		u.Fragment = ""
389		return u.String(), true
390	}
391	
392	// joinOriginPath appends path to the origin root, dropping any base path
393	// carried by the configured origin.
394	func joinOriginPath(origin, path string) string {
395		root, ok := originOf(origin)
396		if !ok {
397			// Should never happen: origins are validated at construction time.
398			return strings.TrimRight(origin, "/") + path
399		}
400		return root + path
401	}
402	
403	func hostKey(origin string) string {
404		u, err := url.Parse(origin)
405		if err != nil || u.Host == "" {
406			return strings.ToLower(origin)
407		}
408		return strings.ToLower(u.Host)
409	}
410	
411	func newNonce() string {
412		b := make([]byte, 8)
413		if _, err := rand.Read(b); err != nil {
414			// crypto/rand failing is exceptional; keep the probe unique anyway.
415			return strconv.FormatInt(time.Now().UnixNano(), 16)
416		}
417		return hex.EncodeToString(b)
418	}
419

